    ('Sets the owner pipeline', "luna-send -n 1 -f luna://com.webos.media/setOwnerPipeline '{}'", ''),
    ('Sets the pipeline media play rate', 'luna-send -n 1 -f luna://com.webos.media/setPlayRate \'{ "playRate":2.0, "mediaId":"_QnGGXr7BdWsOV1", "audioOutput":true }', ''),
    ('Sets the resource policy extra info', "luna-send -n 1 -f luna://com.webos.media/setResourcePolicyExtraInfo '{}'", ''),
    ('Sets subtitle background color for an open media pipeline', 'luna-send -n 1 -f luna://com.webos.media/setSubtitleBackgroundColor \'{"mediaId":"<mediaId>","bgColor":<value>}\'', ''),
